  description?: string; author?: string; authorUrl?: string; license?: string; licenseUrl?: string; rightsStatus?: string; width?: number; height?: number;
  mimeType?: string; fileExtension?: string; isVector?: boolean; category?: string; tags?: string[]; dateCreated?: string;
  collection?: string; publicDomain?: boolean; relevance?: number; sources?: string[]; objectId?: string; iiifInfoUrl?: string; iiifManifestUrl?: string; additionalImageUrls?: string[];
