const DEFAULT_SETTINGS: Settings = { maximumResults: 24, resultsPerProvider: 8, defaultProvider: "all", defaultMode: "General", defaultType: "All", sort: "Best Match", minResolution: 0, vectorPreference: "any", openverseEnabled: true, wikimediaEnabled: true, locEnabled: true, metEnabled: true, archiveEnabled: true, nasaEnabled: true, wikipediaEnabled: true, aicEnabled: true, clevelandEnabled: true, smkEnabled: true, pubchemEnabled: true, rcsbEnabled: true, freeOnly: true, openLicenseOnly: false, safeSearch: true, askAltText: false, addCaption: false, attribution: "none", gridDensity: "comfortable", historySize: 50, cacheDuration: 10, checkConcurrency: 3, history: [], favorites: [], collections: ["Physics Diagrams", "NDA Geography", "History Maps", "Biology", "Chemistry", "SSB"] };
