const HTTP = /^https?:\/\//i;
const IMAGE_EXT = /\.(jpe?g|png|gif|webp|svg|avif)(?:[?#].*)?$/i;
const DIAGRAM_WORDS = ["diagram", "schematic", "labeled", "labelled", "illustration", "cross-section", "structure", "stages", "cycle", "map", "chart", "graph", "timeline", "flowchart", "anatomy", "topology", "circuit", "ray", "free body", "unit cell", "process"];
const MODE_EXPANSIONS: Record<string, string> = { Educational: "educational reference", Diagram: "diagram labeled schematic", Scientific: "scientific figure reference", Mathematics: "mathematics diagram formula", Physics: "physics diagram", Chemistry: "chemistry molecular diagram", Biology: "biology labeled diagram", Geography: "geography reference", History: "historical reference", Maps: "map cartography", Architecture: "architecture plan elevation", Engineering: "engineering technical schematic", Anatomy: "anatomy labeled diagram", Astronomy: "astronomy space science", "Military History": "military history map" };
const TYPE_EXPANSIONS: Record<string, string> = { Diagram: "diagram", Illustration: "illustration", Map: "map", Chart: "chart", Graph: "graph", Scientific: "scientific figure", Photograph: "photograph", Historical: "historical", Architecture: "architecture", Anatomy: "anatomy", Technical: "technical schematic", Vector: "vector SVG", Infographic: "infographic", Timeline: "timeline" };
function s(v: unknown, fallback = ""): string { return typeof v === "string" && v.trim() ? v.trim() : fallback; }
function url(v: unknown): string | undefined { const x = s(v); try { const u = new URL(x); return (u.protocol === "http:" || u.protocol === "https:") ? x : undefined; } catch { return undefined; } }
function cleanTitle(v: string): string { return v.replace(/^File:/i, "").replace(/\.[a-z0-9]{2,5}$/i, "").replace(/[_-]+/g, " ").replace(/\s+/g, " ").trim() || "Image"; }
