function meta(o: Record<string, unknown> | undefined, key: string): string | undefined { const v = o?.[key]; if (typeof v === "string") return v.trim() || undefined; if (v && typeof v === "object" && "value" in v) return s((v as { value?: unknown }).value) || undefined; return undefined; }
function textTokens(v: string): string[] { return v.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, " ").split(/\s+/).filter((x) => x.length > 2); }
async function json(urlText: string): Promise<unknown> { const r = await requestUrl({ url: urlText, method: "GET", headers: { Accept: "application/json", "User-Agent": "Free-Web-Image-Search/2.0" }, throw: false }); if (r.status < 200 || r.status >= 300) throw new Error(`HTTP ${r.status}`); return r.json as unknown; }
function withTimeout<T>(p: Promise<T>, ms = 16000): Promise<T> { return Promise.race([p, new Promise<T>((_, reject) => window.setTimeout(() => reject(new Error("Timed out")), ms))]); }

