class RcsbProvider implements ImageProvider { id = "rcsb"; name = "RCSB Protein Data Bank"; description = "Public macromolecular structure search"; capabilities = CAP({ pagination: true, dimensions: true, directImageUrl: true });
  async search(q: SearchQuery, o: SearchOptions, cursor?: string): Promise<SearchResponse> { const query = encodeURIComponent(JSON.stringify({ query: { type: "terminal", service: "full_text", parameters: { value: q.text } }, return_type: "entry", request_options: { paginate: { start: Number(cursor || 0), rows: Math.min(o.limit, 20) } } })); const d = await json(`https://search.rcsb.org/rcsbsearch/v2/query?json=${query}`) as { result_set?: Array<{ identifier?: string; score?: number }>; total_count?: number }; const results = (d.result_set || []).flatMap((x): ImageResult[] => { const id = s(x.identifier).toLowerCase(); if (!id) return []; const upper = id.toUpperCase(); const imageUrl = `https://cdn.rcsb.org/images/structures/${id}/${id}_assembly-1.jpeg`; return [{ id: upper, title: `${upper} macromolecular structure`, thumbnailUrl: imageUrl, imageUrl, sourceUrl: `https://www.rcsb.org/structure/${upper}`, sourceName: this.name, providerId: this.id, category: "Protein/DNA/RNA structure", fileExtension: "JPG", mimeType: "image/jpeg", relevance: x.score, rightsStatus: "See RCSB PDB source terms" }]; }); return { results, total: d.total_count, nextCursor: results.length ? String(Number(cursor || 0) + results.length) : undefined }; }
}

function expandQuery(q: string, mode: string, type: string, enabled = true): string { if (!enabled) return q; const parts = [q]; if (MODE_EXPANSIONS[mode] && !q.toLowerCase().includes(MODE_EXPANSIONS[mode])) parts.push(MODE_EXPANSIONS[mode]); if (TYPE_EXPANSIONS[type] && type !== "All" && !q.toLowerCase().includes(TYPE_EXPANSIONS[type])) parts.push(TYPE_EXPANSIONS[type]); return parts.join(" "); }
function score(r: ImageResult, query: SearchQuery): number { const q = textTokens(query.text), title = textTokens(`${r.title} ${r.description || ""} ${(r.tags || []).join(" ")}`); let n = q.reduce((a, t) => a + (title.includes(t) ? 8 : 0), 0); if (r.license) n += 3; if (r.author) n += 2; if ((r.width || 0) >= 1280) n += 3; if (r.isVector && ["Diagram", "Technical", "Mathematics", "Physics"].includes(query.mode)) n += 8; if (DIAGRAM_WORDS.some((w) => title.includes(w)) && query.type !== "All") n += 5; n += ({ wikimedia: 7, loc: 6, met: 6, nasa: 5, openverse: 4, archive: 3 }[r.providerId] || 0); return n; }
function dedupe(items: ImageResult[]): ImageResult[] { const map = new Map<string, ImageResult>(); for (const x of items) { const key = (x.imageUrl || x.sourceUrl || `${x.providerId}:${x.title}`).toLowerCase().replace(/[?#].*$/, ""); const old = map.get(key); if (!old) map.set(key, x); else { old.sources = Array.from(new Set([...(old.sources || [old.sourceName]), x.sourceName])); old.author ||= x.author; old.license ||= x.license; old.description ||= x.description; } } return [...map.values()]; }
function markdown(r: ImageResult, alt: string, attribution: Settings["attribution"], caption: boolean): string { const image = `![${alt}](${r.imageUrl})`; let out = image; if (caption) out += `\n\n*${alt}*`; if (attribution === "compact") out += `\n\n*Source: ${r.sourceName}${r.license ? ` · ${r.license}` : ""}*`; if (attribution === "full") { out += `\n\n> Source: ${r.sourceName}\n`; if (r.author) out += `> Author: ${r.author}\n`; if (r.license) out += `> License: ${r.license}\n`; out += `> Original: ${r.sourceUrl}`; } return out; }

export default class FreeWebImageSearchPlugin extends Plugin {
  settings: Settings = structuredClone(DEFAULT_SETTINGS); providers: ImageProvider[] = []; cache = new Map<string, { at: number; value: SearchResponse }>();
  async onload(): Promise<void> { this.settings = Object.assign({}, DEFAULT_SETTINGS, await this.loadData()); this.providers = [new WikimediaProvider(), new OpenverseProvider(), new WikipediaProvider(), new LocProvider(), new MetProvider(), new ArchiveProvider(), new NasaProvider(), new AicProvider(), new ClevelandProvider(), new SmkProvider(), new PubChemProvider(), new RcsbProvider()]; this.addCommand({ id: "search-web-images", name: "Search Images", callback: () => this.openSearch() }); this.addCommand({ id: "search-selected-text", name: "Search images for selected text", editorCallback: (editor) => this.openSearch(editor.getSelection()) }); this.addCommand({ id: "search-current-heading", name: "Search images for current heading", editorCallback: (editor) => this.openSearch(this.heading(editor)) }); this.addCommand({ id: "search-note-title", name: "Search images for current note title", callback: () => this.openSearch(this.app.workspace.getActiveFile()?.basename || "") }); this.addCommand({ id: "search-current-paragraph", name: "Search images for current paragraph", editorCallback: (editor) => this.openSearch(this.paragraph(editor)) }); this.addCommand({ id: "manage-remote-images", name: "Manage Remote Images", callback: () => new RemoteManagerModal(this.app, this).open() }); this.addCommand({ id: "check-remote-images", name: "Check Remote Images", callback: () => new RemoteManagerModal(this.app, this).open() }); this.addRibbonIcon("image-search", "Search web images", () => this.openSearch()); this.addSettingTab(new SettingsTab(this.app, this)); }
  heading(e: Editor): string { const line = e.getLine(e.getCursor().line); return line.replace(/^#+\s*/, "").trim(); }
  paragraph(e: Editor): string { const lines = e.getValue().split(/\n\s*\n/); const pos = e.getCursor().line; let n = 0; for (const p of lines) { const c = p.split("\n").length; if (pos <= n + c) return p.slice(0, 300); n += c; } return ""; }
  openSearch(initial = ""): void { new SearchModal(this.app, this, initial).open(); }
  enabledProviders(selected: string): ImageProvider[] { const enabled: Record<string, boolean> = { wikimedia: this.settings.wikimediaEnabled, openverse: this.settings.openverseEnabled, wikipedia: this.settings.wikipediaEnabled, loc: this.settings.locEnabled, met: this.settings.metEnabled, archive: this.settings.archiveEnabled, nasa: this.settings.nasaEnabled, aic: this.settings.aicEnabled, cleveland: this.settings.clevelandEnabled, smk: this.settings.smkEnabled, pubchem: this.settings.pubchemEnabled, rcsb: this.settings.rcsbEnabled }; return this.providers.filter((p) => (selected === "all" || p.id === selected) && enabled[p.id]); }
  async search(query: SearchQuery, selected: string, cursor?: string): Promise<{ response: SearchResponse; failures: string[]; effective: string }> { const effective = expandQuery(query.text, query.mode, query.type); const key = `${selected}|${effective}|${query.type}|${cursor || ""}|${this.settings.openLicenseOnly}`; const cached = this.cache.get(key); if (cached && Date.now() - cached.at < this.settings.cacheDuration * 60000) return { response: cached.value, failures: [], effective }; const providers = this.enabledProviders(selected); const settled = await Promise.all(providers.map(async (p) => { try { const response = await withTimeout(p.search({ ...query, text: effective }, { limit: this.settings.resultsPerProvider, safeSearch: this.settings.safeSearch, minResolution: this.settings.minResolution, vector: this.settings.vectorPreference }, cursor)); return { response, failure: "" }; } catch (e) { return { response: { results: [] }, failure: `${p.name}: ${e instanceof Error ? e.message : "unavailable"}` }; } })); let results = dedupe(settled.flatMap((x) => x.response.results)); results = results.filter((r) => HTTP.test(r.imageUrl) && HTTP.test(r.thumbnailUrl) && (!this.settings.minResolution || Math.max(r.width || 0, r.height || 0) >= this.settings.minResolution) && (this.settings.vectorPreference !== "only" || r.isVector) && (!this.settings.openLicenseOnly || Boolean(r.publicDomain || r.license || /open access|creative commons|cc0|public domain/i.test(r.rightsStatus || "")))); results.forEach((r) => r.relevance = score(r, query)); this.sortResults(results); const response = { results: results.slice(0, this.settings.maximumResults), nextCursor: settled.map((x) => x.response.nextCursor).find(Boolean), total: settled.reduce((a, x) => a + (x.response.total || 0), 0) }; this.cache.set(key, { at: Date.now(), value: response }); return { response, failures: settled.map((x) => x.failure).filter(Boolean), effective }; }
  sortResults(r: ImageResult[]): void { const mode = this.settings.sort; r.sort((a, b) => mode === "Highest Resolution" ? ((b.width || 0) * (b.height || 0) - (a.width || 0) * (a.height || 0)) : mode === "Vector First" ? Number(Boolean(b.isVector)) - Number(Boolean(a.isVector)) || (b.relevance || 0) - (a.relevance || 0) : (b.relevance || 0) - (a.relevance || 0)); }
  async save(): Promise<void> { await this.saveData(this.settings); }
  isFavorite(r: ImageResult): boolean { return this.settings.favorites.some((x) => x.result.imageUrl === r.imageUrl); }
  toggleFavorite(r: ImageResult): void { const i = this.settings.favorites.findIndex((x) => x.result.imageUrl === r.imageUrl); if (i >= 0) this.settings.favorites.splice(i, 1); else this.settings.favorites.push({ result: r, timestamp: Date.now(), collections: [] }); void this.save(); }
  insert(r: ImageResult, alt?: string, caption?: boolean, attribution?: Settings["attribution"], thumbnail = false): void { const view = this.app.workspace.getActiveViewOfType(MarkdownView); if (!view) { new Notice("Open a Markdown note first."); return; } const image = { ...r, imageUrl: thumbnail ? r.thumbnailUrl : r.imageUrl }; if (!url(image.imageUrl)) { new Notice("Unsafe or invalid image URL."); return; } view.editor.replaceSelection(markdown(image, (alt || r.title).replace(/[\[\]\\]/g, "").trim() || "Image", attribution ?? this.settings.attribution, caption ?? this.settings.addCaption)); new Notice("Remote image URL inserted."); }
  async copy(value: string): Promise<void> { await navigator.clipboard.writeText(value); new Notice("Copied to clipboard."); }
  async checkFiles(files: TFile[], progress?: (n: number, total: number) => void): Promise<RemoteCheck[]> { const out: RemoteCheck[] = []; const re = /!\[([^\]]*)\]\((https?:\/\/[^)\s]+)\)/g; let done = 0; for (const f of files) { const content = await this.app.vault.read(f); const lines = content.split("\n"); lines.forEach((line, idx) => { let m: RegExpExecArray | null; while ((m = re.exec(line))) out.push({ file: f.path, line: idx + 1, alt: m[1], url: m[2], status: "Pending" }); }); done++; progress?.(done, files.length); } let cursor = 0; const worker = async () => { while (cursor < out.length) { const i = cursor++; const item = out[i]; try { const r = await requestUrl({ url: item.url, method: "HEAD", throw: false }); item.status = String(r.status); item.mime = r.headers["content-type"]; } catch { item.status = "Error"; } } }; await Promise.all(Array.from({ length: Math.min(this.settings.checkConcurrency, Math.max(1, out.length)) }, () => worker())); return out; }
}

class SearchModal extends Modal { plugin: FreeWebImageSearchPlugin; input!: HTMLInputElement; results!: HTMLElement; status!: HTMLElement; query: string; provider = "all"; mode: string; type: string; selected = new Set<string>(); nextCursor?: string; effective = ""; searchBtn!: HTMLButtonElement; resultItems: ImageResult[] = [];
  constructor(app: App, plugin: FreeWebImageSearchPlugin, initial: string) { super(app); this.plugin = plugin; this.query = initial; this.mode = plugin.settings.defaultMode; this.type = plugin.settings.defaultType; }
  onOpen(): void { this.modalEl.addClass("fwi-modal"); this.titleEl.setText("Free Web Image Search"); const head = this.contentEl.createDiv("fwi-header"); this.input = head.createEl("input", { type: "search", value: this.query, placeholder: "Search educational diagrams, maps, science…", attr: { "aria-label": "Image search" } }); this.searchBtn = head.createEl("button", { text: "Search", cls: "mod-cta" }); this.searchBtn.onclick = () => void this.run(); this.input.onkeydown = (e) => { if (e.key === "Enter") void this.run(); };
    const controls = this.contentEl.createDiv("fwi-controls"); this.select(controls, "Provider", ["all", "wikimedia", "openverse", "wikipedia", "loc", "met", "archive", "nasa", "aic", "cleveland", "smk", "pubchem", "rcsb"], this.plugin.settings.defaultProvider, (v) => this.provider = v); this.select(controls, "Mode", ["General", ...Object.keys(MODE_EXPANSIONS)], this.mode, (v) => { this.mode = v; this.showEffective(); }); this.select(controls, "Type", ["All", ...Object.keys(TYPE_EXPANSIONS)], this.type, (v) => { this.type = v; this.showEffective(); }); this.select(controls, "Sort", ["Best Match", "Highest Resolution", "Vector First"], this.plugin.settings.sort, (v) => { this.plugin.settings.sort = v; });
    const shortcuts = this.contentEl.createDiv("fwi-shortcuts"); ["Mathematics", "Science", "Geography", "History", "Maps", "Biology", "Physics", "Chemistry", "Astronomy", "Engineering", "Architecture"].forEach((x) => { const b = shortcuts.createEl("button", { text: x }); b.onclick = () => { this.mode = x === "Science" ? "Scientific" : x; this.showEffective(); void this.run(); }; }); this.status = this.contentEl.createDiv({ cls: "fwi-status", attr: { role: "status" } }); this.results = this.contentEl.createDiv({ cls: "fwi-results", attr: { role: "list" } }); this.showEffective(); if (this.query) void this.run(); else this.status.setText("Enter a query. Only the query is sent to providers."); this.input.focus(); }
  select(parent: HTMLElement, label: string, vals: string[], selected: string, change: (v: string) => void): void { const l = parent.createEl("label"); l.createSpan({ text: `${label}:` }); const sEl = l.createEl("select", { attr: { "aria-label": label } }); vals.forEach((v) => sEl.createEl("option", { value: v, text: v[0].toUpperCase() + v.slice(1) })); sEl.value = selected; sEl.onchange = () => change(sEl.value); }
  showEffective(): void { if (!this.status) return; this.status.setText(`Effective search: ${expandQuery(this.input?.value || this.query, this.mode, this.type)}`); }
  async run(cursor?: string): Promise<void> { const q = this.input.value.trim(); if (!q) { this.status.setText("Enter a search term."); return; } if (!cursor) { this.results.empty(); this.nextCursor = undefined; this.resultItems = []; } this.searchBtn.disabled = true; this.status.setText("Searching…"); const r = await this.plugin.search({ text: q, mode: this.mode, type: this.type }, this.provider, cursor); this.searchBtn.disabled = false; this.effective = r.effective; this.nextCursor = r.response.nextCursor; this.resultItems.push(...r.response.results); this.status.setText(`${this.resultItems.length} result${this.resultItems.length === 1 ? "" : "s"}. Effective query: ${this.effective}${r.failures.length ? ` | ${r.failures.join("; ")}` : ""}`); r.response.results.forEach((x) => this.card(x)); if (this.nextCursor) { const more = this.results.createEl("button", { text: "Load more", cls: "fwi-load-more" }); more.onclick = () => { more.remove(); void this.run(this.nextCursor); }; } this.plugin.settings.history = [{ name: q, query: q, mode: this.mode, type: this.type, provider: this.provider, timestamp: Date.now() }, ...this.plugin.settings.history.filter((x) => x.query !== q)].slice(0, this.plugin.settings.historySize); void this.plugin.save(); }
  card(r: ImageResult): void { const card = this.results.createEl("article", { cls: "fwi-card", attr: { tabindex: "0", role: "listitem" } }); const img = card.createEl("img", { attr: { src: r.thumbnailUrl, alt: r.title, loading: "lazy" } }); img.onerror = () => { img.replaceWith(createSpan({ text: "Thumbnail unavailable", cls: "fwi-thumb-error" })); }; const body = card.createDiv("fwi-card-body"); const check = body.createEl("input", { type: "checkbox", attr: { "aria-label": "Select result" } }); check.onchange = () => check.checked ? this.selected.add(r.imageUrl) : this.selected.delete(r.imageUrl); body.createDiv({ text: r.title, cls: "fwi-title" }); body.createDiv({ text: `${r.sourceName}${r.license ? ` · ${r.license}` : ""}`, cls: "fwi-meta" }); body.createDiv({ text: [r.width && r.height ? `${r.width}×${r.height}` : "", r.fileExtension || "", r.isVector ? "Vector" : "", r.iiifInfoUrl ? "IIIF" : "", r.publicDomain ? "Public Domain" : "", r.rightsStatus || "", r.author || ""].filter(Boolean).join(" · "), cls: "fwi-meta" }); const actions = body.createDiv("fwi-actions"); const act = (label: string, fn: () => void) => { const b = actions.createEl("button", { text: label }); b.onclick = (e) => { e.stopPropagation(); fn(); }; }; act("Preview", () => new PreviewModal(this.app, this.plugin, r).open()); act("Insert", () => this.askInsert(r)); act("Copy URL", () => void this.plugin.copy(r.imageUrl)); act("Copy Markdown", () => void this.plugin.copy(markdown(r, r.title, this.plugin.settings.attribution, false))); act(this.plugin.isFavorite(r) ? "Unfavorite" : "Favorite", () => { this.plugin.toggleFavorite(r); }); act("Source", () => window.open(r.sourceUrl)); card.onkeydown = (e) => { if (e.key === "Enter" || e.key.toLowerCase() === "i") this.askInsert(r); if (e.key.toLowerCase() === "c") void this.plugin.copy(r.imageUrl); if (e.key.toLowerCase() === "m") void this.plugin.copy(markdown(r, r.title, this.plugin.settings.attribution, false)); if (e.key.toLowerCase() === "o") window.open(r.sourceUrl); if (e.key.toLowerCase() === "f") this.plugin.toggleFavorite(r); }; card.oncontextmenu = (e) => { e.preventDefault(); const menu = new Menu(); menu.addItem((i) => i.setTitle("Preview").onClick(() => new PreviewModal(this.app, this.plugin, r).open())); menu.addItem((i) => i.setTitle("Insert").onClick(() => this.askInsert(r))); menu.addItem((i) => i.setTitle("Copy Image URL").onClick(() => void this.plugin.copy(r.imageUrl))); menu.addItem((i) => i.setTitle("Open Source").onClick(() => window.open(r.sourceUrl))); menu.showAtMouseEvent(e); }; card.onclick = () => new PreviewModal(this.app, this.plugin, r).open(); }
  askInsert(r: ImageResult): void { if (!this.plugin.settings.askAltText) { this.plugin.insert(r); return; } const alt = window.prompt("Alt text", r.title); if (alt !== null) this.plugin.insert(r, alt); }
  onClose(): void { this.contentEl.empty(); }
}
class PreviewModal extends Modal { constructor(app: App, private plugin: FreeWebImageSearchPlugin, private r: ImageResult) { super(app); } onOpen(): void { this.modalEl.addClass("fwi-preview"); this.titleEl.setText(this.r.title); this.contentEl.createEl("img", { attr: { src: this.r.imageUrl, alt: this.r.title } }); this.contentEl.createDiv({ text: [this.r.sourceName, this.r.author && `Author: ${this.r.author}`, this.r.dateCreated && `Date: ${this.r.dateCreated}`, this.r.collection && `Collection: ${this.r.collection}`, this.r.license && `License: ${this.r.license}`, this.r.rightsStatus && `Rights: ${this.r.rightsStatus}`, this.r.width && this.r.height && `${this.r.width}×${this.r.height}`, this.r.mimeType, this.r.iiifInfoUrl && `IIIF info: ${this.r.iiifInfoUrl}`, this.r.iiifManifestUrl && `IIIF manifest: ${this.r.iiifManifestUrl}`, `Source: ${this.r.sourceUrl}`, `Direct URL: ${this.r.imageUrl}`].filter(Boolean).join("\n"), cls: "fwi-details" }); const row = this.contentEl.createDiv("fwi-actions"); const b = (t: string, f: () => void) => { const x = row.createEl("button", { text: t }); x.onclick = f; }; b("Insert", () => { this.plugin.insert(this.r); this.close(); }); b("Copy URL", () => void this.plugin.copy(this.r.imageUrl)); b("Copy Markdown", () => void this.plugin.copy(markdown(this.r, this.r.title, this.plugin.settings.attribution, false))); b("Open Image", () => window.open(this.r.imageUrl)); b("Open Source", () => window.open(this.r.sourceUrl)); b(this.plugin.isFavorite(this.r) ? "Unfavorite" : "Favorite", () => this.plugin.toggleFavorite(this.r)); } onClose(): void { this.contentEl.empty(); } }
class RemoteManagerModal extends Modal { constructor(app: App, private plugin: FreeWebImageSearchPlugin) { super(app); } async onOpen(): Promise<void> { this.titleEl.setText("Remote Image Health"); this.contentEl.createEl("p", { text: "Checks remote Markdown image URLs only. No files are downloaded or replaced automatically." }); const row = this.contentEl.createDiv("fwi-actions"); const select = row.createEl("select"); ["Current Note", "Current Folder", "Entire Vault"].forEach((x) => select.createEl("option", { text: x, value: x })); const run = row.createEl("button", { text: "Check Remote Images", cls: "mod-cta" }); const out = this.contentEl.createDiv("fwi-health-results"); run.onclick = async () => { run.disabled = true; out.setText("Scanning…"); let files: TFile[] = []; const active = this.app.workspace.getActiveFile(); if (select.value === "Current Note" && active) files = [active]; else if (select.value === "Current Folder" && active) files = this.app.vault.getMarkdownFiles().filter((f) => f.parent?.path === active.parent?.path); else files = this.app.vault.getMarkdownFiles(); const checks = await this.plugin.checkFiles(files, (n, t) => out.setText(`Reading ${n}/${t}…`)); out.empty(); const summary = out.createDiv({ text: `Total: ${checks.length} · Working: ${checks.filter((x) => x.status === "200").length} · Broken/Error: ${checks.filter((x) => x.status !== "200" && x.status !== "Pending").length}` }); checks.forEach((x) => { const line = out.createDiv({ text: `${x.status} · ${x.file}:${x.line} · ${x.alt || "Image"}` }); line.title = x.url; line.onclick = () => window.open(x.url); }); run.disabled = false; }; } onClose(): void { this.contentEl.empty(); } }
class SettingsTab extends PluginSettingTab { constructor(app: App, private plugin: FreeWebImageSearchPlugin) { super(app, plugin); } display(): void { const c = this.containerEl; c.empty(); c.createEl("p", { text: "Find educational and reference images from the open web and insert them into Obsidian as remote URLs." }); new Setting(c).setName("Search").setHeading(); new Setting(c).setName("Default provider").addDropdown((x) => x.addOptions({ all: "All Free Sources", wikimedia: "Wikimedia Commons", openverse: "Openverse", wikipedia: "Wikipedia", loc: "Library of Congress", met: "Met", archive: "Internet Archive", nasa: "NASA", aic: "Art Institute of Chicago", cleveland: "Cleveland Museum of Art", smk: "SMK", pubchem: "PubChem", rcsb: "RCSB PDB" }).setValue(this.plugin.settings.defaultProvider).onChange(async (v) => { this.plugin.settings.defaultProvider = v; await this.plugin.save(); })); new Setting(c).setName("Default educational mode").addDropdown((x) => x.addOptions(Object.fromEntries(["General", ...Object.keys(MODE_EXPANSIONS)].map((v) => [v, v]))).setValue(this.plugin.settings.defaultMode).onChange(async (v) => { this.plugin.settings.defaultMode = v; await this.plugin.save(); })); new Setting(c).setName("Maximum results").addSlider((x) => x.setLimits(6, 48, 6).setValue(this.plugin.settings.maximumResults).setDynamicTooltip().onChange(async (v) => { this.plugin.settings.maximumResults = v; await this.plugin.save(); })); new Setting(c).setName("Results per provider").addSlider((x) => x.setLimits(4, 16, 4).setValue(this.plugin.settings.resultsPerProvider).setDynamicTooltip().onChange(async (v) => { this.plugin.settings.resultsPerProvider = v; await this.plugin.save(); })); new Setting(c).setName("Minimum resolution").addDropdown((x) => x.addOptions({ "0": "Any", "800": "800+", "1280": "1280+", "1920": "1920+" }).setValue(String(this.plugin.settings.minResolution)).onChange(async (v) => { this.plugin.settings.minResolution = Number(v); await this.plugin.save(); })); new Setting(c).setName("Vector preference").addDropdown((x) => x.addOptions({ any: "Any", prefer: "Prefer vector", only: "Vector only" }).setValue(this.plugin.settings.vectorPreference).onChange(async (v) => { this.plugin.settings.vectorPreference = v as Settings["vectorPreference"]; await this.plugin.save(); })); new Setting(c).setName("Access / Rights").setHeading(); new Setting(c).setName("Free / no-user-key sources only").setDesc("Controls API access cost; it does not mean every image is copyright-free.").addToggle((x) => x.setValue(this.plugin.settings.freeOnly).onChange(async (v) => { this.plugin.settings.freeOnly = v; await this.plugin.save(); })); new Setting(c).setName("Open license only").setDesc("Show only results with returned open/public rights metadata.").addToggle((x) => x.setValue(this.plugin.settings.openLicenseOnly).onChange(async (v) => { this.plugin.settings.openLicenseOnly = v; await this.plugin.save(); })); new Setting(c).setName("Insertion / Attribution").setHeading(); new Setting(c).setName("Ask for alt text").addToggle((x) => x.setValue(this.plugin.settings.askAltText).onChange(async (v) => { this.plugin.settings.askAltText = v; await this.plugin.save(); })); new Setting(c).setName("Add caption").addToggle((x) => x.setValue(this.plugin.settings.addCaption).onChange(async (v) => { this.plugin.settings.addCaption = v; await this.plugin.save(); })); new Setting(c).setName("Attribution").addDropdown((x) => x.addOptions({ none: "None", compact: "Compact", full: "Full" }).setValue(this.plugin.settings.attribution).onChange(async (v) => { this.plugin.settings.attribution = v as Settings["attribution"]; await this.plugin.save(); })); new Setting(c).setName("No-Key Providers").setHeading(); const providers: Array<[string, keyof Settings]> = [["Wikimedia Commons", "wikimediaEnabled"], ["Openverse", "openverseEnabled"], ["Wikipedia", "wikipediaEnabled"], ["Library of Congress", "locEnabled"], ["Metropolitan Museum of Art", "metEnabled"], ["Internet Archive", "archiveEnabled"], ["NASA Image Library", "nasaEnabled"], ["Art Institute of Chicago", "aicEnabled"], ["Cleveland Museum of Art", "clevelandEnabled"], ["SMK", "smkEnabled"], ["PubChem", "pubchemEnabled"], ["RCSB PDB", "rcsbEnabled"]]; providers.forEach(([name, key]) => new Setting(c).setName(name).addToggle((x) => x.setValue(Boolean(this.plugin.settings[key])).onChange(async (v) => { (this.plugin.settings[key] as boolean) = v; await this.plugin.save(); }))); new Setting(c).setName("Privacy / Health").setHeading(); c.createEl("p", { text: "No note content is uploaded. Only explicit search queries are sent. No analytics or telemetry are collected. No image files are downloaded into the vault." }); new Setting(c).setName("Remote check concurrency").addSlider((x) => x.setLimits(1, 8, 1).setValue(this.plugin.settings.checkConcurrency).setDynamicTooltip().onChange(async (v) => { this.plugin.settings.checkConcurrency = v; await this.plugin.save(); })); new Setting(c).setName("Clear history").addButton((b) => b.setButtonText("Clear").onClick(async () => { this.plugin.settings.history = []; await this.plugin.save(); new Notice("Search history cleared."); })); new Setting(c).setName("Clear favorites").addButton((b) => b.setButtonText("Clear").onClick(async () => { this.plugin.settings.favorites = []; await this.plugin.save(); new Notice("Favorites cleared."); })); new Setting(c).setName("Clear cache").addButton((b) => b.setButtonText("Clear").onClick(() => { this.plugin.cache.clear(); new Notice("Search cache cleared."); })); new Setting(c).setName("About").setHeading(); c.createEl("p", { text: "Free Web Image Search 3.0 · verified no-key APIs, IIIF-aware museum images, rights-aware filtering, and deterministic search." }); } }
